function(container, apiUrl, tables) {
  let selectedStores = new Set();
  let currentModel = null;
  let isProcessing = false;

  // 現在日時を適用開始日時のデフォルトに設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#start-datetime').value = now.toISOString().slice(0, 16);

  // モデル一覧を読み込み
  async function loadModels() {
    const models = await window.aivicApi.list(0); // 需要予測結果テーブル
    const modelSelect = container.querySelector('#model-select');

    if (models) {
      // 検証済みモデルのみ表示（予測ステータスが完了のもの）
      const validatedModels = models.filter(m => m.予測ステータス === '完了');
      validatedModels.forEach(model => {
        const option = document.createElement('option');
        option.value = model.id;
        option.textContent = `${model.予測モデルバージョン} (精度: ${model.予測精度}%)`;
        modelSelect.appendChild(option);
      });
    }
  }

  // 店舗一覧を読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeList = container.querySelector('#store-list');

    if (stores) {
      const activeStores = stores.filter(s => s.有効フラグ);
      storeList.innerHTML = activeStores.map(store => `
        <label style="display: block; margin-bottom: 8px;">
          <input type="checkbox" class="store-checkbox" data-store-id="${store.id}">
          ${store.店舗名} (${store.店舗コード})
        </label>
      `).join('');
    }
  }

  // 選択店舗数を更新
  function updateSelectedCount() {
    container.querySelector('#selected-count').textContent = `選択店舗数: ${selectedStores.size}`;
  }

  // モデル詳細情報を表示
  async function showModelDetails(modelId) {
    const models = await window.aivicApi.list(0);
    if (models) {
      currentModel = models.find(m => m.id === modelId);
      if (currentModel) {
        const detailsDiv = container.querySelector('#model-details');
        const infoDiv = container.querySelector('#model-info');

        infoDiv.innerHTML = `
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
            <div>
              <strong>モデルバージョン:</strong> ${currentModel.予測モデルバージョン}<br>
              <strong>予測精度:</strong> ${currentModel.予測精度}%<br>
              <strong>作成日時:</strong> ${new Date(currentModel.作成日時).toLocaleString()}
            </div>
            <div>
              <strong>ステータス:</strong> ${currentModel.予測ステータス}<br>
              <strong>対象商品数:</strong> ${currentModel.推奨発注数量 || 'N/A'}<br>
              <strong>備考:</strong> ${currentModel.備考 || 'なし'}
            </div>
          </div>
        `;

        detailsDiv.classList.remove('hidden');
        showValidationResults();
        updateImpactAnalysis();

        // ロールバックボタンの状態を更新
        container.querySelector('#btn-rollback').disabled = currentModel.予測ステータス !== '承認済み';
      }
    }
  }

  // 検証結果を表示
  function showValidationResults() {
    if (!currentModel) return;

    const resultsDiv = container.querySelector('#validation-results');
    const isValidated = currentModel.予測ステータス === '完了';

    resultsDiv.innerHTML = `
      <div style="display: flex; align-items: center; margin-bottom: 12px;">
        <span style="width: 12px; height: 12px; border-radius: 50%; background: ${isValidated ? '#28a745' : '#dc3545'}; margin-right: 8px;"></span>
        <strong>${isValidated ? '検証完了' : '検証未完了'}</strong>
      </div>
      <div>
        <strong>予測精度:</strong> ${currentModel.予測精度}%<br>
        <strong>検証期間:</strong> ${new Date(currentModel.作成日時).toLocaleDateString()}<br>
        <strong>検証結果:</strong> ${isValidated ? '本番適用可能' : '検証が必要です'}
      </div>
    `;
  }

  // 影響範囲分析を更新
  function updateImpactAnalysis() {
    if (!currentModel || selectedStores.size === 0) {
      container.querySelector('#impact-analysis').innerHTML = '<div class="muted">店舗とモデルを選択すると影響範囲が表示されます</div>';
      return;
    }

    const estimatedTime = Math.ceil(selectedStores.size * 2); // 1店舗あたり2分と仮定
    const impactDiv = container.querySelector('#impact-analysis');

    impactDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
        <div>
          <strong>影響店舗数:</strong> ${selectedStores.size}店舗<br>
          <strong>予想処理時間:</strong> 約${estimatedTime}分<br>
          <strong>影響商品カテゴリ:</strong> 全カテゴリ
        </div>
        <div>
          <strong>現行モデル:</strong> 自動バックアップ<br>
          <strong>ダウンタイム:</strong> なし<br>
          <strong>ロールバック可能期間:</strong> ${container.querySelector('#retention-days').value}日間
        </div>
      </div>
      ${selectedStores.size > 10 ? '<div style="color: #ffc107; margin-top: 12px;"><strong>⚠️ 大規模適用:</strong> 10店舗以上への適用は処理時間が長くなります</div>' : ''}
    `;
  }

  // 適用処理を実行
  async function executeApply() {
    // バリデーション
    if (!currentModel) {
      alert('適用対象のモデルが選択されていません');
      return;
    }

    if (currentModel.予測ステータス !== '完了') {
      alert('検証が完了していないモデルは本番適用できません');
      return;
    }

    if (selectedStores.size === 0) {
      alert('適用対象の店舗が選択されていません');
      return;
    }

    const startDateTime = new Date(container.querySelector('#start-datetime').value);
    const now = new Date();
    if (startDateTime < now) {
      alert('適用日時は現在日時以降を指定してください');
      return;
    }

    const retentionDays = parseInt(container.querySelector('#retention-days').value);
    if (retentionDays <= 0) {
      alert('現行モデル保持期間は1日以上を指定してください');
      return;
    }

    if (isProcessing) {
      alert('既に適用処理が実行中です。処理完了後に再度実行してください。');
      return;
    }

    if (!confirm(`${selectedStores.size}店舗にモデル「${currentModel.予測モデルバージョン}」を適用しますか？`)) {
      return;
    }

    isProcessing = true;
    container.querySelector('#btn-apply').disabled = true;
    container.querySelector('#progress-section').classList.remove('hidden');
    container.querySelector('#result-log-section').classList.remove('hidden');

    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const resultLog = container.querySelector('#result-log');

    // 進捗シミュレーション
    let progress = 0;
    const totalSteps = selectedStores.size;

    resultLog.innerHTML = `[${new Date().toLocaleTimeString()}] 適用処理を開始しました\n`;

    for (let i = 0; i < totalSteps; i++) {
      await new Promise(resolve => setTimeout(resolve, 1000)); // 1秒待機

      progress = ((i + 1) / totalSteps) * 100;
      progressBar.style.width = `${progress}%`;
      progressText.textContent = `処理中... ${i + 1}/${totalSteps} 店舗完了`;

      resultLog.innerHTML += `[${new Date().toLocaleTimeString()}] 店舗 ${i + 1} の適用が完了しました\n`;
      resultLog.scrollTop = resultLog.scrollHeight;
    }

    // 適用完了処理
    progressText.textContent = '適用完了';
    resultLog.innerHTML += `[${new Date().toLocaleTimeString()}] 全店舗への適用が正常に完了しました\n`;

    // モデルステータスを更新
    await window.aivicApi.update(0, currentModel.id, {
      予測ステータス: '本番適用中',
      備考: `${selectedStores.size}店舗に適用完了`
    });

    isProcessing = false;
    container.querySelector('#btn-apply').disabled = false;
    container.querySelector('#btn-rollback').disabled = false;

    alert('モデルの本番適用が完了しました');
  }

  // ロールバック処理を実行
  async function executeRollback() {
    if (!currentModel) {
      alert('ロールバック対象のモデルが選択されていません');
      return;
    }

    if (currentModel.予測ステータス !== '本番適用中' && currentModel.予測ステータス !== '承認済み') {
      alert('適用前のため、ロールバックできません');
      return;
    }

    if (!confirm('モデルをロールバックしますか？以前のバージョンに戻ります。')) {
      return;
    }

    container.querySelector('#btn-rollback').disabled = true;
    container.querySelector('#progress-section').classList.remove('hidden');
    container.querySelector('#result-log-section').classList.remove('hidden');

    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const resultLog = container.querySelector('#result-log');

    resultLog.innerHTML = `[${new Date().toLocaleTimeString()}] ロールバック処理を開始しました\n`;

    // ロールバック進捗シミュレーション
    for (let i = 0; i <= 100; i += 20) {
      await new Promise(resolve => setTimeout(resolve, 500));
      progressBar.style.width = `${i}%`;
      progressText.textContent = `ロールバック中... ${i}%`;
    }

    // ロールバック完了処理
    await window.aivicApi.update(0, currentModel.id, {
      予測ステータス: 'ロールバック完了',
      備考: 'ロールバック実行済み'
    });

    progressText.textContent = 'ロールバック完了';
    resultLog.innerHTML += `[${new Date().toLocaleTimeString()}] ロールバック処理が正常に完了しました\n`;

    container.querySelector('#btn-rollback').disabled = false;
    alert('ロールバック処理が完了しました');
  }

  // イベントリスナー設定
  container.querySelector('#model-select').addEventListener('change', (e) => {
    if (e.target.value) {
      showModelDetails(e.target.value);
    } else {
      container.querySelector('#model-details').classList.add('hidden');
      currentModel = null;
    }
    updateApplyButtonState();
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedStores.add(cb.dataset.storeId);
      } else {
        selectedStores.delete(cb.dataset.storeId);
      }
    });
    updateSelectedCount();
    updateImpactAnalysis();
    updateApplyButtonState();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      if (e.target.checked) {
        selectedStores.add(e.target.dataset.storeId);
      } else {
        selectedStores.delete(e.target.dataset.storeId);
      }
      updateSelectedCount();
      updateImpactAnalysis();
      updateApplyButtonState();
    }
  });

  container.querySelector('#retention-days').addEventListener('input', updateImpactAnalysis);

  function updateApplyButtonState() {
    const applyBtn = container.querySelector('#btn-apply');
    applyBtn.disabled = !currentModel || selectedStores.size === 0 || isProcessing;
  }

  container.querySelector('#btn-apply').addEventListener('click', executeApply);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期データ読み込み
  loadModels();
  loadStores();
}
